package main
import("context";"errors";"flag";"fmt";"log/slog";"net";"net/http";"os";"os/signal";"syscall";"time";"github.com/TelkomIndonesia/oauth2-sidecar/internal/auth";"github.com/TelkomIndonesia/oauth2-sidecar/internal/config";"github.com/TelkomIndonesia/oauth2-sidecar/internal/proxy";"github.com/TelkomIndonesia/oauth2-sidecar/internal/token")
var version="dev"
func main(){c,action,e:=config.Parse(os.Args[1:],os.Getenv);if errors.Is(e,flag.ErrHelp){return};if e!=nil{fmt.Fprintln(os.Stderr,e);os.Exit(2)};if action==config.ActionVersion{fmt.Println(version);return};s:=token.NewFileStore(c.TokenStore);if action==config.ActionLogout{e=s.Delete(context.Background());if e!=nil&&!errors.Is(e,token.ErrNotFound){panic(e)};return};p,e:=auth.NewProvider(context.Background(),c.Issuer);if e!=nil{panic(e)};a:=auth.NewAuthenticator(p,c);m:=token.NewManager(s,a);if c.Login{_,e=m.Token(context.Background())}else{_,e=m.Token(context.Background())};if e!=nil{panic(e)};log:=slog.Default();pr,e:=proxy.New(c.Upstream,m,log);if e!=nil{panic(e)};ln,e:=net.Listen("tcp",c.Listen);if e!=nil{panic(e)};defer ln.Close();if host,_,_:=net.SplitHostPort(ln.Addr().String());host!="127.0.0.1"&&host!="::1"{log.Warn("non-loopback listen address", "address",ln.Addr().String())};srv:=&http.Server{Handler:pr,ReadHeaderTimeout:10*time.Second,IdleTimeout:90*time.Second};ctx,stop:=signal.NotifyContext(context.Background(),syscall.SIGINT,syscall.SIGTERM);defer stop();go func(){<-ctx.Done();q,cancel:=context.WithTimeout(context.Background(),10*time.Second);defer cancel();srv.Shutdown(q)}();if e=srv.Serve(ln);e!=nil&&!errors.Is(e,http.ErrServerClosed){panic(e)}}
